/bin/bash -lc "python3 - <<'PY'
from html.parser import HTMLParser
from pathlib import Path
import subprocess
class Check(HTMLParser):
    def __init__(self):
        super().__init__(); self.stack=[]; self.errors=[]
    def handle_starttag(self, tag, attrs):
        if tag not in {'meta','link','img','input','br','hr','source','wbr','area','base','col','embed','param','track','path','circle'}: self.stack.append(tag)
    def handle_endtag(self, tag):
        if tag in {'path','circle'}: return
        if not self.stack or self.stack[-1] "'!= tag: self.errors.append((tag, self.stack[-5:]))
        else: self.stack.pop()
s=Path('"'index.html').read_text(); p=Check(); p.feed(s)
print('HTML nesting:', 'PASS' if not p.errors and not p.stack else (p.errors,p.stack))
js=s.split('<script>')[1].split('</script>')[0]
r=subprocess.run(['node','--check'],input=js,text=True,capture_output=True)
print('JavaScript syntax:', 'PASS' if r.returncode == 0 else r.stderr)
print('Ingredients:',s.count('<li><label>'))
PY"

